/* ── Fallback: letter avatar ──────────────────────────────────────── */

function LetterIcon({ name, size, color }: { name: string; size: number; color: string }) {
  const letter = name.charAt(0).toUpperCase();
  return (
    <svg width={size} height={size} viewBox="0 0 24 24">
      <text
        x="12"
        y="16.5"
        textAnchor="middle"
        fill={color}
        fontSize="15"
        fontWeight="600"
        fontFamily="system-ui, sans-serif"
      >
        {letter}
      </text>
    </svg>
  );
}

export function getTechColor(name: string): string {
  return tech[name]?.color ?? "#a0a0a0";
}

export function getTechLogo(
  name: string,
  size = 16,
  colorOverride?: string
): ReactNode {
  const entry = tech[name];
  const color = colorOverride ?? getTechColor(name);
  return entry ? (
    entry.icon({ size, color })
  ) : (
    <LetterIcon name={name} size={size} color={color} />
  );
}

/* ── Exported component — expanding pill on hover ─────────────────── */

interface TechIconProps {
  name: string;
  size?: number;
}

export function TechIcon({ name, size = 16 }: TechIconProps) {
  const [hovered, setHovered] = useState(false);
  const entry = tech[name];
  const color = entry?.color ?? "#a0a0a0";

  return (
    <motion.div
      layout
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      className="flex items-center gap-1.5 h-8 rounded-full border border-dashed border-border dark:border-dark-border hover:border-solid hover:border-border-hover dark:hover:border-dark-border-hover bg-surface dark:bg-dark-surface cursor-default overflow-hidden"
      style={{ paddingLeft: 7, paddingRight: hovered ? 10 : 7 }}
      transition={{ type: "spring", stiffness: 500, damping: 30 }}
    >
      <motion.div
        layout="position"
        className="shrink-0 w-4.5 h-4.5 flex items-center justify-center"
      >
        {entry ? (
          entry.icon({ size, color })
        ) : (
          <LetterIcon name={name} size={size} color={color} />
        )}
      </motion.div>
      {hovered && (
        <motion.span
          initial={{ opacity: 0, width: 0 }}
          animate={{ opacity: 1, width: "auto" }}
          exit={{ opacity: 0, width: 0 }}
          transition={{ duration: 0.2, ease: [0.4, 0, 0.2, 1] }}
          className="text-[12px] font-medium text-text dark:text-dark-text whitespace-nowrap overflow-hidden"
        >
          {name}
        </motion.span>
      )}
    </motion.div>
  );
}
